function JudgeProgress({jobState,runs,onReplay}:{jobState:any;runs:any[];onReplay:()=>void}){if(jobState?.type!=="judge-demo")return null;const group=jobState.job_id,saved=runs.filter(r=>r.experiment_group?.type==="judge-demo"&&r.experiment_group?.id===group),stages=["benchmark","noise","mitigation"],at=jobState.status==="completed"?3:Math.min(2,Math.floor(Number(jobState.progress||0)/34));const score=(run:any,model:string)=>{const m=run?.metrics?.find((x:any)=>x.model===model&&x.metric==="PR-AUC");return m?`${Number(m.mean).toFixed(3)} ± ${Number(m.std||0).toFixed(3)}`:"—"};return <Section title="Judge demo · staged evidence" desc="A staged showcase, not a paired full-protocol comparison. Noise uses the controlled balanced subset."><div className="judge-stages">{stages.map((stage,i)=><div className={i<at?"done":i===at&&["running","queued"].includes(jobState.status)?"active":""} key={stage}><b>{i+1}/3</b><span>{stage==="benchmark"?"Ideal benchmark":stage==="noise"?"Simulated noise":"ZNE mitigation"}</span><small>{i<saved.length?"Saved":i===at?jobState.message:"Waiting"}</small></div>)}</div><progress max="100" value={jobState.progress||0}/>{jobState.status==="completed"&&saved.length===3&&<div className="sweep-table"><table><thead><tr><th>Stage</th><th>Quantum PR-AUC</th><th>Classical PR-AUC</th><th>Run</th></tr></thead><tbody>{stages.map(stage=>{const r=saved.find(x=>x.experiment_group.configuration.stage===stage);return <tr key={stage}><td>{stage}</td><td>{score(r,stage==="benchmark"?"Quantum ideal":stage==="noise"?"noisy":"mitigated-linear")}</td><td>{stage==="benchmark"?score(r,"Best classical (CV-selected)"):"Separate noise protocol"}</td><td>{r?.run_id||"—"}</td></tr>})}</tbody></table><p>Mitigation results are reported even when they do not improve on noisy performance.</p></div>}{runs.some(r=>r.experiment_group?.type==="judge-demo")&&<button className="btn outline" onClick={onReplay}>Replay stored judge-demo evidence</button>}</Section>}
